/**
 * Sprint 34R — Decision Support Response Draft Quality Evaluation: fixtures.
 *
 * Scenario descriptors used by
 * `tests/playbook-engine-conversation-decision-support-response-draft-quality-evaluation.test.mjs`. Each
 * entry documents one behavior this sprint must exhibit — some carry a `sourceCase` (a minimal
 * `{ caseId, routeKind, responseKind }` shape, exactly what a Sprint 32R response QA case assessment
 * already carries) that the test file feeds through `createDecisionSupportResponseDraftFromQaCase()` +
 * `validateDecisionSupportResponseDraft()` to build a Sprint 33R-shaped case result; others (e.g.
 * "attempt to enable X blocked") describe a config-level invariant the test file checks directly, and use
 * neutral placeholders for the fields that do not apply.
 *
 * This fixture never imports from `src/`, and is never imported by production code — it exists only for
 * this sprint's own test suite.
 */

export type DecisionSupportResponseDraftQualityFixtureSourceCase = {
  caseId: string;
  routeKind: string;
  responseKind: string;
};

export type DecisionSupportResponseDraftQualityFixtureCase = {
  id: string;
  scenario: string;
  dimension: string;
  draftKind: string;
  expectedScoreRange: [number, number];
  expectedStatus: string;
  expectedRiskLevel: string;
  expectedScoreBand: string;
  expectedIssues: string[];
  expectedSafeForUserVisibleDryRunHarness: boolean;
  expectedSafeForUserVisibleOutputNow: boolean;
  expectedSafeForProduction: boolean;
  notes: string;
  /** Present only for scenarios that build/score a real synthetic draft. */
  sourceCase?: DecisionSupportResponseDraftQualityFixtureSourceCase;
  /** Present only for the thirteen "attempt to enable X blocked" config scenarios. */
  configOverrideField?:
    | "allowUserVisibleOutput"
    | "allowProductionWiring"
    | "allowRouterChange"
    | "allowComposerChange"
    | "allowEndpointChange"
    | "allowFeatureFlag"
    | "allowRealPersistence"
    | "allowDbWrite"
    | "allowSupabaseWrite"
    | "allowExternalCalls"
    | "allowActionExecution"
    | "allowTaskCreation"
    | "allowEmailDraftCreation";
};

